// ATOM2_06 · Setup Pipedrive · planejadores (3 Code nodes leem daqui; ver n8n/sdk/build_setup_pd.js).
// Fonte: 03_FUNIS_PIPEDRIVE.md §3, §4 e §6. Idempotente: compara por nome; o que já existe vira GET inofensivo.
// Cada planejador devolve itens { method, url, body, ref } para um único nó HTTP Request (método e URL por expressão).
const API = 'https://api.pipedrive.com/v1';
const NOOP = { method: 'GET', url: API + '/users/me', body: {} };

// Fases do "Fluxo do Funil Comercial v1.0" (09/10/2026): ganho = aceite (F11); formalização (F12) e produção (F13) acompanham por campos depois do ganho.
const FUNIS = [
  { chave: 'OUT', nome: 'Prospecção Ativa', etapas: [
    ['PRONTO', 'Abordagem autorizada', 5, null], ['CADENCIA', 'Contatado (cadência)', 10, 18], ['RESPONDEU', 'Respondeu', 20, 3],
    ['QUALIFICADO', 'Qualificado', 30, 5], ['N2', 'Diagnóstico N2', 40, 5], ['REUNIAO', 'Reunião agendada', 50, null],
    ['PROPOSTA', 'Proposta', 65, 7], ['NEGOCIACAO', 'Negociação', 80, 7]
  ] },
  { chave: 'IN', nome: 'Atendimento Receptivo', etapas: [
    ['NOVO', 'Novo lead', 10, 1], ['ATENDIMENTO', 'Em atendimento', 20, 3], ['QUALIFICADO', 'Qualificado', 35, 3],
    ['REUNIAO', 'Reunião agendada', 50, null], ['PROPOSTA', 'Proposta', 65, 5], ['NEGOCIACAO', 'Negociação', 80, 5]
  ] }
];
// Campos da seção 7 do Fluxo do Funil que ainda não existem (dominio, nicho, Serviço, IDs Autentique/Asaas, Status do contrato/pagamento e "Não contatar" já existem: VERIFICADO 09/10/2026).
const CAMPOS = [
  ['ORIGEM', 'ATOM · Origem', 'enum', ['Prospecção ativa', 'Receptivo']],
  ['CANAL', 'ATOM · Canal', 'enum', ['WhatsApp nº 1', 'WhatsApp nº 2', 'Formulário do site', 'Google Ads', 'Meta Ads', 'Indicação', 'Ligação', 'E-mail', 'Outro']],
  ['UTM', 'ATOM · Campanha / UTM', 'varchar'],
  ['OFERTA', 'ATOM · Oferta de interesse', 'enum', ['Clínica completa', 'Marketing com IA', 'Agente de IA', 'Site']],
  ['COMPANY_ID', 'ATOM · company_id', 'varchar'],
  ['AUDIT_ID', 'ATOM · audit_n1_id', 'varchar'],
  ['FINDING_ID', 'ATOM · finding_id', 'varchar'],
  ['EVIDENCE_URL', 'ATOM · URL da evidência', 'varchar'],
  ['EVIDENCE_DATE', 'ATOM · Data da evidência', 'date'],
  ['SCORE', 'ATOM · Score N1', 'double'],
  ['FAIXA', 'ATOM · Faixa N1', 'enum', ['A', 'B', 'C']],
  ['QA_STATUS', 'ATOM · QA', 'enum', ['Pendente', 'Aprovado', 'Reprovado']],
  ['PERMISSAO', 'ATOM · Permissão de contato', 'enum', ['Não avaliada', 'Autorizada', 'Negada', 'Opt-out']],
  ['TEMPLATE', 'ATOM · Template', 'varchar'],
  ['TOQUE', 'ATOM · Passo da cadência', 'enum', ['D1', 'D3', 'D6', 'D9', 'D12', 'Encerrada']],
  ['ULTIMO_CONTATO', 'ATOM · Último contato', 'date'],
  ['INTENCAO', 'ATOM · Intenção da resposta', 'enum', ['Pode enviar', 'Quanto custa', 'Tenho interesse', 'Já tenho agência', 'Mande proposta', 'Agora não', 'Sem interesse', 'Opt-out', 'Ambígua']],
  ['QUALIFICACAO', 'ATOM · Qualificação', 'enum', ['Pendente', 'Qualificado', 'Sem perfil']],
  ['REUNIAO', 'ATOM · Status da reunião', 'enum', ['Agendada', 'Realizada', 'Não compareceu', 'Reagendada', 'Cancelada']],
  ['N2_URL', 'ATOM · Link do diagnóstico N2', 'varchar'],
  ['PROPOSTA_ID', 'ATOM · proposal_id', 'varchar'],
  ['PROXIMA_ACAO', 'ATOM · Próxima ação', 'varchar']
];

const dados = (r) => (r && Array.isArray(r.data) ? r.data : []);
const igual = (a, b) => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase();

function planejarFunis(pipelines) {
  return FUNIS.map((f) => {
    const existe = dados(pipelines).find((p) => igual(p.name, f.nome));
    return existe ? { ...NOOP, ref: 'funil:' + f.chave, existente: existe.id } : { method: 'POST', url: API + '/pipelines', body: { name: f.nome, deal_probability: 1 }, ref: 'funil:' + f.chave };
  });
}
function planejarEtapas(pipelines, stages) {
  const out = [];
  for (const f of FUNIS) {
    const p = dados(pipelines).find((x) => igual(x.name, f.nome));
    if (!p) throw new Error('Funil não encontrado após criação: ' + f.nome);
    for (const [chave, nome, prob, rot] of f.etapas) {
      const existe = dados(stages).find((s) => s.pipeline_id === p.id && igual(s.name, nome));
      out.push(existe ? { ...NOOP, ref: 'etapa:' + f.chave + ':' + chave, existente: existe.id }
        : { method: 'POST', url: API + '/stages', body: { name: nome, pipeline_id: p.id, deal_probability: prob, rotten_flag: rot !== null, rotten_days: rot }, ref: 'etapa:' + f.chave + ':' + chave });
    }
  }
  return out;
}
function planejarCampos(fields) {
  return CAMPOS.map(([chave, nome, tipo, opcoes]) => {
    const existe = dados(fields).find((c) => igual(c.name, nome));
    if (existe) return { ...NOOP, ref: 'campo:' + chave, existente: existe.key };
    const body = { name: nome, field_type: tipo };
    if (opcoes) body.options = opcoes.map((label) => ({ label }));
    return { method: 'POST', url: API + '/dealFields', body, ref: 'campo:' + chave };
  });
}
// Linhas para atom2_config com todos os IDs (lidos de novo depois das criações).
function resumir(pipelines, stages, fields) {
  const linhas = [];
  const linha = (chave, valor, descricao) => linhas.push({ chave, valor: String(valor), status: 'CONFIGURADO', descricao });
  for (const f of FUNIS) {
    const p = dados(pipelines).find((x) => igual(x.name, f.nome));
    linha('PD2_PIPE_' + f.chave + '_ID', p.id, 'Funil "' + f.nome + '" no Pipedrive (03_FUNIS_PIPEDRIVE.md)');
    for (const [chave, nome] of f.etapas) {
      const s = dados(stages).find((x) => x.pipeline_id === p.id && igual(x.name, nome));
      linha('PD2_STAGE_' + f.chave + '_' + chave + '_ID', s.id, 'Etapa "' + nome + '" do funil ' + f.nome);
    }
  }
  for (const [chave, nome, tipo] of CAMPOS) {
    const c = dados(fields).find((x) => igual(x.name, nome));
    linha('PD2_FIELD_' + chave, c.key, 'Chave do campo de negócio "' + nome + '"');
    if (tipo === 'enum') for (const o of c.options || []) linha('PD2_OPT_' + chave + '_' + String(o.label).normalize('NFD').replace(/\p{M}/gu, '').toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_|_$/g, ''), o.id, 'Opção "' + o.label + '" de ' + nome);
  }
  return linhas;
}

return planejarFunis($('Ler funis').first().json).map((j) => ({ json: j }));

